     const fields = [
       {
         input: document.getElementById("full-name"),
         error: document.getElementById("full-name-error"),
         validate: (value) => (value.trim() ? "" : "Full name is required.")
       },
       {
         input: document.getElementById("email-address"),
         error: document.getElementById("email-address-error"),
         validate: (value) => {
           const trimmed = value.trim();

           if (!trimmed) {
             return "Email address is required.";
           }

           if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmed)) {
             return "Enter a valid email address.";
           }

           return "";
         }
       },
       {
         input: document.getElementById("phone-number"),
         error: document.getElementById("phone-number-error"),
         validate: (value) => {
           const trimmed = value.trim();

           if (!trimmed) {
             return "";
           }

           if (!/^\+?[0-9()\s.-]{7,}$/.test(trimmed)) {
             return "Enter a valid phone number or leave this field blank.";
           }

           return "";
         }
